def get_coeffs(k, n0):
    # coeffs[k][j] is a dictionary {i: coefficient}
    coeffs = [[{} for _ in range(n0 + k*(n0-1) + 1)] for k in range(k+1)]

    for i in range(1, n0 + 1):
        coeffs[0][i][i] = 1

    for step in range(1, k+1):
        # The number of terms at step step-1 is n_{step-1}
        # n_k = 2^k(n0-1) + 1
        # But we can just use the existing coeffs.
        # The indices of coeffs[step-1] are 1 to n_{step-1}
        # Let's find the max index used in coeffs[step-1]
        max_idx = 0
        for j in range(len(coeffs[step-1])):
            if coeffs[step-1][j]:
                max_idx = max(max_idx, j)

        # The indices of coeffs[step] are 1 to 2*max_idx - 1
        # Wait, the number of terms is n_k = 2^k(n0-1) + 1
        # Let's just iterate through the range of j.
        # For step-1, the terms are at indices 1 to n_{step-1}.
        # The new terms are at 1 to 2*n_{step-1} - 1.
        n_prev = max_idx
        for j in range(1, 2*n_prev):
            if j % 2 == 1:
                # x_{step, j} = x_{step-1, (j+1)/2}
                prev_j = (j + 1) // 2
                coeffs[step][j] = coeffs[step-1][prev_j].copy()
            else:
                # x_{step, j} = x_{step-1, j/2} + x_{step-1, j/2 + 1}
                prev_j1 = j // 2
                prev_j2 = j // 2 + 1
                combined = coeffs[step-1][prev_j1].copy()
                for i, val in coeffs[step-1][prev_j2].items():
                    combined[i] = combined.get(i, 0) + val
                coeffs[step][j] = combined
    return coeffs

