        for i in range(len(S) - 1):
            new_S.append(S[i] + S[i+1])
            new_S.append(S[i+1])
        S = new_S
    return S.count(target)

for k in range(1, 10):
    n0 = 1000
    print(f"k={k}, count={find_counts(k, n0, 2013)}")
